arguments.command:
$paths = @('C:\temp\1791939998026-copilot-tool-output-17df698187c94317a162913674a718ae.txt','C:\temp\1791939997534-copilot-tool-output-39c897cf0a79411cb8e5356a7b0f433a.txt','C:\temp\1791939998341-copilot-tool-output-fdcdaa4249494a399384c509047c98a6.txt')
$pattern = 'Tailscale Funnel|tailscale|funnel|cloudflare|cloudflared|honk'
foreach ($path in $paths) {
  $text = [IO.File]::ReadAllText($path)
  $matches = [regex]::Matches($text, $pattern, [Text.RegularExpressions.RegexOptions]::IgnoreCase)
  Write-Output "===== $(Split-Path $path -Leaf): $($matches.Count) match(es) ====="
  $seen = @{}
  $i = 0
  foreach ($m in $matches) {
    $i++
    if ($i -gt 30) { Write-Output "... truncated after 30 matches ..."; break }
    $start = [Math]::Max(0, $m.Index - 350)
    $len = [Math]::Min(900, $text.Length - $start)
    $snippet = $text.Substring($start, $len) -replace "`r?`n", " "
    Write-Output "--- match $i ($($m.Value)) at char $($m.Index) ---"
    Write-Output $snippet
    Write-Output ""
  }
}

