arguments.command:
$files = @('workcrew_chatgpt_1.md','workcrew_chatgpt_2.md','workcrew_chatgpt_3.md','protocrew_deepseek_5.md','protocore_claude_1.md','canon\doctrines.md','deepseek_to_korylos.md','workcrew_chatgpt_2.md')
$pattern = 'Tailscale Funnel|dc-proxy|DevSpace|Hob Hole|local MCP server wrapped in an HTTP proxy|honk|Goose'
foreach ($file in $files) {
  if (-not (Test-Path $file)) { continue }
  $text = [IO.File]::ReadAllText((Resolve-Path $file))
  $matches = [regex]::Matches($text, $pattern, [Text.RegularExpressions.RegexOptions]::IgnoreCase)
  if ($matches.Count -eq 0) { continue }
  Write-Output "===== $file ($($matches.Count) match(es)) ====="
  $shown = 0
  foreach ($m in $matches) {
    $shown++
    if ($shown -gt 8) { Write-Output "... truncated ..."; break }
    $start = [Math]::Max(0, $m.Index - 280)
    $len = [Math]::Min(700, $text.Length - $start)
    $snippet = $text.Substring($start, $len) -replace "`r?`n", " "
    Write-Output "--- $($m.Value) @ $($m.Index) ---"
    Write-Output $snippet
    Write-Output ""
  }
}

